import os, csv
import numpy as np
import sys
sys.path.append('storage/shared/agents/kairos')
import avd

OUT_DIR = 'storage/shared/agents/kairos/avd'
os.makedirs(OUT_DIR, exist_ok=True)

def to_float(x):
    try:
        return float(x)
    except Exception:
        return None

def main():
    dists = ['beta07_08','beta09_09','exponential2']
    n, seed = 150, 42
    ratios = np.linspace(0.0, 1.0, 11)

    out_csv = os.path.join(OUT_DIR, 'avd_emergence_info.csv')
    with open(out_csv, 'w', encoding='utf-8', newline='') as f:
        wr = csv.writer(f)
        wr.writerow(['distribution','ratio','synergy','expected_info','H','Hmax','emergence_info'])
        for dist in dists:
            balanced, high_var = avd.generate_data(dist, n, seed)
            best = {'ratio': None, 'emergence': -1.0}
            emergence_curve = []
            for r in ratios:
                data = high_var * float(r) + balanced * (1.0 - float(r))
                syn = avd.synergy(data)['synergy']
                H, Hmax, exp_info = avd.info_entropy_baseline(data, bins=32)
                emer = None
                if exp_info is not None and exp_info > 1e-12 and syn is not None:
                    emer = float(syn) / float(exp_info) - 1.0
                emergence_curve.append((float(r), emer))
                wr.writerow([dist, float(r), syn, exp_info, H, Hmax, emer])
                if emer is not None and emer > best['emergence']:
                    best = {'ratio': float(r), 'emergence': emer}

    # Summary
    by_dist = {}
    with open(out_csv, 'r', encoding='utf-8') as f:
        rd = csv.DictReader(f)
        for row in rd:
            d = row['distribution']
            by_dist.setdefault(d, []).append({
                'ratio': to_float(row['ratio']),
                'emer': to_float(row['emergence_info'])
            })
    summary_path = os.path.join(OUT_DIR, 'avd_emergence_info.txt')
    with open(summary_path, 'w', encoding='utf-8') as f:
        f.write("AVD v0.3.1 — Info-theoretic expected synergy baseline\n")
        for d, lst in by_dist.items():
            lst = sorted(lst, key=lambda x: x['ratio'])
            # argmax
            best_i, best_v = 0, -1e9
            for i, p in enumerate(lst):
                v = p['emer'] if p['emer'] is not None else -1e9
                if v > best_v:
                    best_v, best_i = v, i
            f.write(f"- {d}: best_r_info={lst[best_i]['ratio']}, emergence_info@1.0={lst[-1]['emer']}\n")
        f.write(f"csv={out_csv}\n")

    print(f"[artifacts] {out_csv} | {summary_path}")

if __name__ == "__main__":
    main()
